const sectionTitle=(eyebrow,title,desc='',right='')=>`<div class="section-title"><div><div class="eyebrow dark">${eyebrow}</div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${right}</div>`;
const solvedCount=(course,topic,p)=>practiceQuestions.filter(q=>(!course||q.course===course)&&(!topic||q.topic===topic)&&p.correctQuestions.includes(q.id)).length;
const questionCount=(course,topic)=>practiceQuestions.filter(q=>(!course||q.course===course)&&(!topic||q.topic===topic)).length;
const attemptCount=p=>Object.values(p.attemptedQuestions||{}).reduce((a,b)=>a+b,0);
const testAttempts=(id,p)=>p.scores.filter(s=>s.testId===id);
const bestTestScore=(id,p)=>{const rows=testAttempts(id,p);return rows.length?Math.max(...rows.map(s=>Math.round(s.score/s.max*100))):null};
const courseLabel=id=>courseById(id)?.short||id;

